import sys

def find_initial_set(n, d, l):
    if n == 2:
        if abs(d) > l:
            return -1
        return [l, l + d] if d >= 0 else [l - d, l]

    for x in range(1, l + 1):
        result = find_initial_set(n - 1, d + x, l)
        if result != -1:
            return [x] + result
    return -1

n, d, l = map(int, sys.stdin.read().strip().split())
result = find_initial_set(n, d, l)
if result == -1:
    print(-1)
else:
    print(' '.join(map(str, result)))
